OLD = {
    "id":          {"type": "string", "required": True},
    "status":      {"type": "string", "required": True},
    "total_cents": {"type": "int",    "required": True},
    "currency":    {"type": "string", "required": True},
    "note":        {"type": "string", "required": False},
}

NEW = {
    "id":          {"type": "string", "required": True},
    "status":      {"type": "int",    "required": True},
    "currency":    {"type": "string", "required": True},
    "note":        {"type": "string", "required": True},
    "amount":      {"type": "int",    "required": True},
    "tags":        {"type": "list",   "required": False},
}


def diff_contract(old, new):
    diffs = []
    for field, spec in old.items():
        if field not in new:
            diffs.append((field, "BREAKING", "removed: consumers read it"))
            continue
        nspec = new[field]
        if nspec["type"] != spec["type"]:
            diffs.append((field, "BREAKING", f"type changed {spec['type']} -> {nspec['type']}"))
        elif not spec["required"] and nspec["required"]:
            diffs.append((field, "BREAKING", "request field now required"))
        elif spec["required"] and not nspec["required"]:
            diffs.append((field, "SAFE", "loosened obligation"))
    for field, nspec in new.items():
        if field in old:
            continue
        if nspec["required"]:
            diffs.append((field, "BREAKING", "new required field breaks old writers"))
        else:
            diffs.append((field, "SAFE", "additive optional"))
    return diffs


def decide_version(diffs):
    if any(v == "BREAKING" for _, v, _ in diffs):
        return "v2 required (breaking changes present)"
    return "v1 (ship in place)"


diffs = diff_contract(OLD, NEW)
for field, verdict, reason in diffs:
    print(f"{verdict:8s} {field}: {reason}")
breaking = sum(1 for _, v, _ in diffs if v == "BREAKING")
print(f"breaking_changes: {breaking}")
print(f"decision: {decide_version(diffs)}")

data-architecture.code:
PATHS = {
    "browse-grid":      {"contract": "eventual", "max_stale_s": 30},
    "product-page":     {"contract": "eventual", "max_stale_s": 5},
    "checkout-capture": {"contract": "strong"},
    "fraud-batch":      {"contract": None},
}

TIMELINE = [
    ("write", 0,   "v1"),
    ("write", 100, "v2"),
    ("read",  102, "browse-grid",      "v1"),
    ("read",  104, "product-page",     "v1"),
    ("read",  105, "checkout-capture", "v2"),
    ("write", 200, "v3"),
    ("read",  230, "browse-grid",      "v2"),
    ("read",  208, "product-page",     "v2"),
    ("read",  210, "checkout-capture", "v2"),
    ("read",  800, "fraud-batch",      "v1"),
]


def audit_paths(paths, timeline):
    replaced_at = {}   # version -> time it stopped being latest
    prev_version = None
    for entry in timeline:
        if entry[0] == "write":
            _, t, version = entry
            if prev_version is not None:
                replaced_at[prev_version] = t
            prev_version = version
    reports = {name: {"max_stale_s": 0, "breaches": 0} for name in paths}
    for entry in timeline:
        if entry[0] != "read":
            continue
        _, t, path, version = entry
        stale = max(0, t - replaced_at[version]) if version in replaced_at else 0
        rep = reports[path]
        rep["max_stale_s"] = max(rep["max_stale_s"], stale)
        contract = paths[path]["contract"]
        if contract == "strong" and stale > 0:
            rep["breaches"] += 1
        elif contract == "eventual" and stale > paths[path]["max_stale_s"]:
            rep["breaches"] += 1
    for name, rep in reports.items():
        if paths[name]["contract"] is None:
            rep["status"] = "UNCONTRACTED"
        elif rep["breaches"] > 0:
            rep["status"] = "BREACH"
        else:
            rep["status"] = "OK"
    return reports


reports = audit_paths(PATHS, TIMELINE)
for name in PATHS:
    r = reports[name]
    print(f"{name}: max_stale={r['max_stale_s']}s breaches={r['breaches']} -> {r['status']}")
worst = max(reports.values(), key=lambda r: r["max_stale_s"])["max_stale_s"]
print(f"worst_observed_staleness: {worst}s (on an uncontracted path)")

consistency-transactions.code:
class Crash(Exception):
    pass

ORDERS = [1, 2, 3, 4, 5, 6]
CRASH_PLAN = {2: "after-db", 4: "in-tx", 5: "after-publish"}


def run_naive(orders, crash_plan):
    db_orders, bus = [], []
    for oid in orders:
        try:
            crash_at = crash_plan.get(oid)
            if crash_at == "in-tx":
                raise Crash()
            db_orders.append(oid)
            if crash_at == "after-db":
                raise Crash()
            bus.append(oid)
        except Crash:
            pass
    return db_orders, bus


def run_outbox(orders, crash_plan):
    db_orders, outbox, bus = [], [], []
    crashed_once = set()
    for oid in orders:
        try:
            crash_at = crash_plan.get(oid)
            if crash_at == "in-tx":
                raise Crash()          # before the tx commits: neither row lands
            db_orders.append(oid)      # atomic: order row + outbox row together
            outbox.append({"id": oid, "sent": False})
        except Crash:
            pass

    def relay_tick():
        for row in outbox:
            if row["sent"]:
                continue
            try:
                bus.append(row["id"])
                if crash_plan.get(row["id"]) == "after-publish" and row["id"] not in crashed_once:
                    crashed_once.add(row["id"])
                    raise Crash()      # published but never marked sent
                row["sent"] = True
            except Crash:
                pass

    relay_tick()   # tick 1: order 5 publishes then crashes before mark_sent
    relay_tick()   # tick 2: order 5 re-publishes (duplicate) and is marked sent
    return db_orders, bus


def consume(bus, seen=None):
    seen = set() if seen is None else seen
    effects = 0
    for oid in bus:
        if oid in seen:
            continue
        seen.add(oid)
        effects += 1
    return effects


n_db, n_bus = run_naive(ORDERS, CRASH_PLAN)
o_db, o_bus = run_outbox(ORDERS, CRASH_PLAN)

n_lost = [oid for oid in n_db if oid not in n_bus]
print(f"naive:  committed={len(n_db)} events={len(n_bus)} lost_events={n_lost}")
print(f"outbox: committed={len(o_db)} events_on_bus={len(o_bus)} (duplicates included)")
print(f"outbox_consumer_effects: {consume(o_bus)} (exactly one per committed order: {sorted(set(o_db)) == sorted(set(o_bus))})")
print(f"invariant 'no committed order without event': naive={'HOLDS' if not n_lost else 'VIOLATED'} outbox={'HOLDS' if set(o_db) <= set(o_bus) else 'VIOLATED'}")

