PACKET = {
    "constraints": [
        {"name": "no-event-loss"},
        {"name": "write-p99-120ms"},
        {"name": "replay-30d"},
    ],
    "decisions": [
        {"name": "post-commit-publish",
         "addresses": ["no-event-loss"],
         "rejected": "dual-write", "rejected_reason": "can lose events",
         "rejected_reason_also_applies": True,
         "verification": "unit tests cover publish success and failure paths"},
        {"name": "sync-publish-on-write-path",
         "addresses": ["write-p99-120ms"],
         "rejected": None, "rejected_reason": None,
         "rejected_reason_also_applies": False,
         "verification": "queue p99 measured at 38ms at 9600 events/s under rebalance"},
    ],
}


def trace_packet(packet):
    findings = []
    addressed = set()
    for d in packet["decisions"]:
        addressed.update(d["addresses"])
    for c in packet["constraints"]:
        if c["name"] not in addressed:
            findings.append(f"C:{c['name']} UNTRACED - no selected approach addresses it")
    for d in packet["decisions"]:
        if d["rejected"] is None:
            findings.append(f"D:{d['name']} no rejected alternative - tradeoff hidden")
        elif d["rejected_reason_also_applies"]:
            findings.append(f"D:{d['name']} rejection reason also applies to selected approach")
        if not any(ch.isdigit() for ch in d["verification"]):
            findings.append(f"D:{d['name']} verification has no number - not falsifiable")
    n = len(findings)
    findings.append(f"review: BLOCKED ({n} finding(s))" if n else "review: PASS")
    return findings


for f in trace_packet(PACKET):
    print(f)

architecture-proof-packet.code:
HUMAN_DETECTORS = ["customer complains", "support ticket", "someone notices"]

PACKET = {
    "claims": [
        {"text": "constraint forces async",
         "evidence": "no-daytime-downtime + staleness <= 5 min kills sync dual-write and nightly batch"},
        {"text": "handles projected load",
         "evidence": "1200 writes/s x 2KB = 2.4 MB/s; rebuild 104M events in under 2h at 16k docs/s"},
        {"text": "cheaper than sync path",
         "evidence": "removes the double-write amplification from the write path"},
    ],
    "failures": [
        {"mode": "worker crash",   "blast_radius": "index stales, bounded by lag alarm",
         "detection": "index_lag_seconds > 60 pages"},
        {"mode": "queue backlog",  "blast_radius": "staleness grows, no loss",
         "detection": "queue_depth > 100k alerts"},
        {"mode": "poison doc",     "blast_radius": "one doc unindexed, parked",
         "detection": "customer complains"},
        {"mode": "index corrupt",  "blast_radius": "",
         "detection": "nightly checksum diff alerts"},
    ],
    "reversal": "if p99 index lag > 5 min for 2h OR rebuild > 4h, revert reads to sync path",
}


def has_digit(s):
    return any(ch.isdigit() for ch in (s or ""))


def validate_packet(packet):
    findings = []
    for c in packet["claims"]:
        if not has_digit(c["evidence"]):
            findings.append(f"claim '{c['text']}' evidence has no number - assertion, not proof")
    for fm in packet["failures"]:
        if not fm["blast_radius"]:
            findings.append(f"failure '{fm['mode']}' has no blast radius")
        if not fm["detection"] or fm["detection"] in HUMAN_DETECTORS:
            findings.append(f"failure '{fm['mode']}' not machine-detectable ({fm['detection']})")
    if not has_digit(packet["reversal"]):
        findings.append("reversal condition not measurable")
    n = len(findings)
    findings.append("packet: SIGNED" if n == 0 else f"packet: REJECTED ({n} gaps)")
    return findings


for f in validate_packet(PACKET):
    print(f)
